"""Additional kernel libraries with independent contracts and worked examples."""
def register(topic,q,detail):
    topic('Generic Radix Tree·희소 고정 크기 객체','라이브러리·알고리즘','lib/generic-radix-tree.c','__genradix_ptr_alloc',
      '큰 index 공간에 고정 크기 객체를 드문드문 저장할 때 전체 배열을 처음부터 할당하지 않을 수 있습니다.',
      'Genradix는 page 단위 leaf와 내부 pointer node로 byte offset을 분해해 저장 공간을 찾습니다. 필요한 가지를 할당하고 offset이 기존 depth 밖이면 root 깊이를 늘립니다. 새 slot은 zero 초기화되지만 없는 slot 조회와 할당 조회는 다른 API입니다.',
      '타입을 선언한 genradix API로 index를 변환하고 ptr과 ptr_alloc을 구분합니다. GFP·할당 실패·동시 접근·free 수명을 관리하며 slot pointer를 tree 해제 이후 사용하지 않습니다.',
      '__genradix_ptr_alloc의 depth 검사·new_root·cmpxchg와 include/linux/generic-radix-tree.h의 index 변환을 읽으세요.',
      q('아주 큰 index의 하나만 사용하면 모든 앞선 객체를 채워야 하는가?','해당 offset으로 이어지는 가지를 마련한다','중간의 모든 객체를 반드시 생성한다','희소 tree는 필요한 page와 node를 준비합니다. 전체 배열 공간과 실제 저장 공간을 구분해야 합니다.'),
      q('새 slot이 zero 초기화되면 객체의 모든 논리 초기화가 끝난 것인가?','lock·list·상태 등 타입의 초기화는 별도로 한다','0은 모든 C 객체의 완전한 초기 상태다','Zeroed storage와 객체의 유효 상태는 다릅니다. List 자기참조나 lock·참조 count 등은 해당 API 초기화가 필요합니다.'),
      details=[detail('Byte Offset','내부 함수는 객체 index가 아니라 offset을 받습니다. Typed wrapper의 객체 크기·page 경계 변환을 확인해야 직접 index를 byte 주소로 혼동하지 않습니다.'),detail('공개와 수명','Node 설치의 atomic 경합 처리가 사용자 객체의 모든 동시 갱신을 직렬화하지는 않습니다. Tree 구조 접근과 slot 내부 상태 보호를 구분합니다.')])
    topic('Timerqueue·가장 가까운 만료의 Tree','라이브러리·알고리즘','lib/timerqueue.c','timerqueue_add',
      '가장 가까운 만료를 자주 조회하면서 임의 타이머를 삽입·삭제할 때 순서 tree와 최소값 cache가 유용합니다.',
      'Timerqueue는 expires 기준 red-black tree와 cached leftmost node를 사용합니다. Add는 새 node가 가장 이른 만료인지 반환하고 delete는 제거 후 queue가 비어 있지 않은지를 반환합니다. 함수별 bool 의미가 다르며 라이브러리 자체는 locking을 하지 않습니다.',
      'head·node를 초기화하고 외부 lock 등으로 모든 조작을 직렬화합니다. 이미 들어간 node를 다시 add하지 않으며 만료 변경은 올바른 제거·재삽입 규칙으로 정렬 불변식을 유지합니다.',
      'timerqueue_add·timerqueue_del·timerqueue_iterate_next를 전부 읽고 반환 bool을 비교하세요.',
      q('기존 만료 30·50에 20을 add하면 bool의 의미는?','새 node가 첫 만료이므로 true','queue가 세 개라 false','Add는 새 node가 leftmost인지 반환합니다. Queue 비어 있음 검사와 같은 의미가 아닙니다.'),
      q('Timerqueue 함수가 자체 spinlock으로 모든 thread 접근을 보호하는가?','호출자가 직렬화해야 한다','모든 함수에 숨겨진 global mutex가 있다','파일 시작 주석은 locking을 하지 않고 모든 함수를 serialize해야 한다고 명시합니다.'),
      details=[detail('Delete','rb_erase_cached 후 RB_CLEAR_NODE로 node 상태를 정리합니다. 반환값은 남은 queue가 비어 있지 않은지입니다. 제거된 node가 가장 이른지의 뜻으로 읽지 않습니다.'),detail('Next','NULL이면 NULL을 반환하고 rb_next로 순서상 다음 node를 찾습니다. 순회 중 변경과 객체 해제를 막는 수명·lock은 별도입니다.'),detail('Comparator와 매크로','__node_2_tq는 rb_entry로 embedded rb_node에서 소유 timerqueue_node를 찾습니다. __timerqueue_less는 expires의 엄격한 < 비교이며 동일 만료는 이 비교에서 더 작지 않습니다. Tree 내 node의 만료값을 직접 바꾸면 정렬 불변식이 깨질 수 있습니다.'),detail('경고는 오류 반환이 아니다','Add는 이미 연결된 node에 WARN_ON_ONCE를, delete는 empty node에 WARN_ON_ONCE를 사용합니다. 경고 뒤에도 tree 조작을 진행하므로 잘못된 사용을 안전하게 거부하는 validation API라고 생각하면 안 됩니다. Caller가 초기화·중복 삽입·제거·수명을 지켜야 합니다.'),detail('파일의 나머지 선언','linux/timerqueue.h는 구조체·초기화, rbtree.h는 cached tree API, bug.h는 경고, export.h는 심볼 공개를 제공합니다. EXPORT_SYMBOL_GPL 세 개는 함수의 runtime 순서를 실행하는 문장이 아니라 모듈이 심볼을 사용하도록 하는 빌드·연결 정보입니다.')])
    topic('Lockref·잠금과 참조의 결합','라이브러리·알고리즘','lib/lockref.c','lockref_get_not_zero',
      '참조 갱신과 객체 잠금 상태를 한 atomic 단위에서 다루면 경합이 없는 획득의 lock 비용을 줄일 수 있습니다.',
      'Lockref는 lock과 count가 들어 있는 표현에서 지원되는 cmpxchg 빠른 경로를 사용하고 실패·지원 조건에 따라 spinlock 경로로 갑니다. Get_not_zero는 count가 양수일 때만 증가시키며 0 또는 dead 계열의 상태를 되살리지 않습니다.',
      'Lockref 초기화와 get/put 변형별 반환·dead 상태 규약을 따릅니다. 이미 free된 주소에서 get을 시도하지 않도록 lookup 수명을 별도로 보호하고 모든 helper를 일반 refcount_t와 동일하게 취급하지 않습니다.',
      'lockref_get_not_zero의 CMPXCHG_LOOP와 lock 아래 count>0 분기를 비교하세요.',
      q('Count가 0이면 get_not_zero가 1로 되살리는가?','실패 0을 반환한다','항상 count를 증가시킨다','빠른 경로는 old.count<=0이면 반환하고 느린 경로도 count>0일 때만 증가합니다. 종료된 객체를 임의 부활시키지 않습니다.'),
      q('Lockref 빠른 경로가 있으면 모든 객체 필드를 동시에 수정해도 되는가?','참조·lock 계약과 필드 보호를 따로 확인한다','모든 필드가 같은 atomic word다','Count 갱신의 원자성과 여러 field 불변식은 다릅니다. 해당 객체의 lock·lookup 수명 규약을 지켜야 합니다.'),
      details=[detail('Fallback','CMPXCHG 조건이 맞지 않으면 spin_lock 아래 같은 목적의 count 검사를 합니다. 빠른 경로와 느린 경로가 같은 의미를 유지하는지 비교합니다.'),detail('반환값','이 helper는 획득 성공 여부를 1/0으로 반환합니다. 감소 helper 중에는 count나 특별값을 반환하는 것도 있어 이름만으로 타입 의미를 추정하지 않습니다.')])
    topic('RCURef·경합과 Dead 상태','라이브러리·알고리즘','lib/rcuref.c','rcuref_put_slowpath',
      '마지막 put과 동시 get이 경합할 때 누가 객체를 종료할 권리를 얻었는지 명확히 해야 합니다.',
      'RCURef는 NOREF·DEAD·saturation 등 특수 count 영역으로 경합과 수명 상태를 표현합니다. 마지막 put 느린 경로는 NOREF를 DEAD로 cmpxchg 전환해야 해제 가능 true를 반환합니다. 동시 get/put으로 전환이 실패하면 해당 caller는 해체하면 안 됩니다.',
      'rcuref get/put API와 RCU lookup·지연 해제 규약을 함께 사용합니다. Encoded 값과 실제 참조 수를 구분하고 반환 true를 받은 종료 주체가 적절한 grace period·해제를 수행합니다.',
      'rcuref_put_slowpath의 NOREF→DEAD release cmpxchg와 acquire after control dependency를 읽으세요.',
      q('NOREF→DEAD cmpxchg가 실패한 caller가 객체를 해체해도 되는가?','false이므로 이 caller는 해체하면 안 된다','NOREF를 한번 봤으니 무조건 free한다','동시 get이 count를 올렸거나 다른 put이 이미 DEAD로 만든 경우가 있습니다. 단일 종료 권한을 얻지 못한 caller는 free하지 않습니다.'),
      q('RCURef라는 이름만으로 caller가 즉시 free해도 항상 안전한가?','RCU 독자와 지연 해제 계약도 따른다','DEAD 값은 모든 pointer를 자동 삭제한다','Ref 상태 전환과 이미 공개된 pointer를 보는 RCU reader 수명은 연결된 별도 조건입니다.'),
      details=[detail('Imbalanced Put','Dead zone에서 추가 put은 잘못된 균형으로 경고하고 해체 권한을 다시 주지 않습니다. Double free를 방지하는 상태 규약을 읽습니다.'),detail('Memory Ordering','마지막 참조 감소의 release와 성공 전환 뒤 acquire ordering이 객체 종료 전에 필요한 관찰을 연결합니다. 수명 규약 없이 배리어만 추가하는 해결과는 다릅니다.')])
    topic('Klist·참조가 있는 목록 순회','라이브러리·알고리즘','lib/klist.c','klist_next',
      '순회하는 동안 다른 흐름이 node 제거를 요청해도 현재 객체를 안전하게 유지할 수 있어야 합니다.',
      'Klist는 list node와 kref·dead 상태·get/put callback을 결합합니다. Iterator는 현재 node 참조를 유지하고 next에서 기존 참조를 내려놓고 살아 있는 다음 node의 참조를 얻습니다. 목록 보호 lock과 객체 callback 수명은 연결되지만 별도 역할입니다.',
      'Klist와 node를 초기화하고 iterator init·next·exit를 균형 있게 호출합니다. Get/put callback과 del/remove의 대기 규약을 확인하며 iterator가 끝나기 전에 잡은 객체를 무조건 free하지 않습니다.',
      'klist_next의 spinlock·klist_dec_and_del·knode_dead 건너뛰기·kref_get·unlock 후 put을 읽으세요.',
      q('klist_next가 dead node를 발견하면 그 node를 정상 다음 항목으로 반환하는가?','건너뛰고 다음 살아 있는 node를 찾는다','항상 첫 pointer를 반환한다','원본은 !knode_dead일 때만 kref_get하고 i_cur로 선택합니다. 논리 제거 상태와 연결 위치를 구분합니다.'),
      q('Iterator를 중간에 멈추면 exit 정리가 필요 없는가?','현재 참조를 정리하는 iterator 종료 규약을 따른다','지역 변수 iterator는 어떤 참조도 없다','Iterator는 현재 node 참조를 보유할 수 있습니다. 순회 중단과 객체 수명을 정리해야 제거가 완료될 수 있습니다.'),
      details=[detail('Unlock 뒤 Callback','원본은 목록 spinlock을 풀고 기존 node의 put callback을 호출합니다. Callback이 수행할 작업의 context와 잠금 범위를 구분하는 사례입니다.'),detail('Node와 Object','목록 node는 객체 안의 멤버일 수 있습니다. Reference callback이 실제 외부 객체 수명과 연결되어야 node가 살아 있어도 container가 사라지는 오류를 막습니다.')])
    topic('LRU Cache·고정 객체와 교체 상태','라이브러리·알고리즘','lib/lru_cache.c','lc_get',
      '제한된 수의 객체를 label로 조회하면서 사용 중 객체와 교체 후보·미완료 변경을 구분해야 합니다.',
      'lib/lru_cache는 active set을 고정된 element로 관리하며 label hash·LRU/free·to_be_changed 목록과 refcount를 연결합니다. 새 label을 위한 교체는 transaction 상태와 commit 규약을 가집니다. 일반 page reclaim LRU와 같은 자료형이 아닙니다.',
      'lc_create·get/try_get·put·commit 관련 API 계약을 따르고 외부 locking·element label·pending 변경을 관리합니다. Cumulative get으로 얻은 미완료 element는 pending transaction 완료 전 실제 사용하면 안 됩니다.',
      'lc_get·lc_get_cumulative·__lc_get와 LC_GET_MAY_USE_UNCOMMITTED를 비교하세요.',
      q('lc_get_cumulative가 pending 변경 element를 반환하면 즉시 확정 data로 사용해도 되는가?','transaction 완료 전제부터 만족한다','pointer 반환은 항상 commit 완료다','원본 주석은 to_be_changed element를 반환할 수 있고 caller가 pending transaction 완료를 보장해야 한다고 명시합니다.'),
      q('lc_try_get은 없는 label을 위해 active set을 항상 바꾸는가?','존재 항목 조회와 교체 허용을 구분한다','try_get도 언제나 신규 label을 설치한다','API별 flags와 계약이 다릅니다. 조회·참조 증가와 새로운 label로 교체하는 동작을 구분합니다.'),
      details=[detail('참조 중 교체','현재 사용 중 element와 LRU 후보를 구분해야 다른 label로 바꾸면서 기존 사용자의 data를 손상시키지 않습니다.'),detail('Commit','미완료 변경의 새 label과 현재 label을 추적합니다. 저장·transaction 계약을 완료한 뒤 active mapping을 확정하는 흐름을 읽습니다.')])
    topic('Objpool·CPU별 객체 Ring','라이브러리·알고리즘','include/linux/objpool.h','objpool_pop',
      '할당하기 어려운 interrupt·probe 경로에서 준비된 객체를 CPU별 ring에서 가져오면 일반 allocation 비용을 줄일 수 있습니다.',
      'Objpool은 고정 capacity의 per-CPU ring array를 사용하며 head·tail·last sequence와 mask로 slot 예약·공개·소비를 분리합니다. CAS와 acquire/release가 경합을 처리하고 pop은 local부터 다른 possible CPU slot을 탐색할 수 있습니다.',
      'objpool_init으로 객체를 준비하고 pop 실패 NULL을 처리합니다. 사용 후 push하거나 종료 중 outstanding object를 drop하는 계약을 따릅니다. 같은 객체 중복 push·잘못된 객체 반환·fini와 진행 중 push 경합을 금지합니다.',
      'objpool_pop·__objpool_try_get_slot·__objpool_try_add_slot와 fini 주석을 함께 읽으세요.',
      q('Objpool의 object 초기화 callback은 매 pop마다 자동 호출되는가?','최초 준비 때 한번이며 재사용 초기화는 caller 책임이다','모든 pop이 새 zero 객체를 만든다','헤더는 objinit이 초기 할당 직후 한번만 호출되며 이후 내용 재초기화·정리는 caller 책임이라고 명시합니다.'),
      q('Fini 뒤 아직 사용하는 객체가 있을 수 있으면?','outstanding object의 drop과 pool 참조 수명을 따른다','fini는 진행 중 사용자 pointer까지 즉시 안전하게 지운다','비동기 사용은 마지막 outstanding 객체의 drop까지 pool 수명을 유지할 수 있습니다. 진행 중 push 종료도 caller가 보장해야 합니다.'),
      details=[detail('예약과 공개','Tail을 예약한 것과 entries의 pointer가 소비 가능하게 공개된 것은 다릅니다. Last와 release ordering이 준비된 객체의 경계를 나타냅니다.'),detail('한계','생성 후 객체 수가 고정되고 CPU별 ring이 list보다 더 많은 메모리를 쓸 수 있습니다. Lockless queue 성질이 무한 capacity·무실패 allocation을 뜻하지 않습니다.')])
    topic('Parman·우선순위 정렬 배열 관리','라이브러리·알고리즘','lib/parman.c','parman_item_add',
      'Hardware table처럼 index 순서가 우선순위를 나타낼 때 항목 추가로 주변 구간을 이동해야 합니다.',
      'Parman은 priority별 item 그룹과 array index를 관리하고 알고리즘의 add/remove 및 caller move·resize callback으로 저장 배치를 맞춥니다. Priority 순서와 같은 priority의 item 범위를 보존하며 logical item과 물리 index 수명은 다릅니다.',
      'Priority와 item을 초기화하고 ops의 move·resize가 실제 table 배치를 갱신하도록 구현합니다. 모든 locking은 caller가 제공하며 callback 실패·capacity·동시 lookup과 이동 조건을 확인합니다.',
      'parman_item_add의 algo->item_add와 priority 알고리즘의 이동·resize를 읽으세요.',
      q('Parman item의 index가 항목 수명 내내 절대 변하지 않는가?','정렬을 유지하며 이동할 수 있다','index는 영구 object ID다','Array 위치는 priority 배치에 따라 바뀔 수 있습니다. ID와 table index를 구분하고 move callback으로 실제 내용을 맞춥니다.'),
      q('Parman API가 자체 lock으로 여러 caller를 직렬화하는가?','caller가 모든 locking을 제공한다','move callback만 있으면 경합이 사라진다','원본 API 주석이 외부 locking을 요구합니다. Index 이동과 hardware 갱신을 다른 접근과 조정해야 합니다.'),
      details=[detail('Callback','관리 라이브러리는 어떤 index를 옮길지 정하지만 실제 hardware·배열 data 변경은 caller operations가 담당합니다.'),detail('우선순위 구간','같은 priority의 그룹과 전체 그룹 순서를 유지합니다. 항목 하나를 삽입할 때 원소 복사 비용이 생길 수 있어 검색 tree의 비용과 다릅니다.')])
    topic('Errseq·비동기 오류 관찰 순서','라이브러리·알고리즘','lib/errseq.c','errseq_check_and_advance',
      'Writeback처럼 오류가 나중에 발생할 때 여러 observer가 각자 마지막 확인 이후 오류를 보아야 합니다.',
      'Errseq는 오류 번호·sequence·seen 상태를 encoded 값에 담고 observer의 since와 비교합니다. Check_and_advance는 새로운 상태면 오류를 반환하고 observer 위치를 앞으로 옮깁니다. 모든 event의 개별 로그가 아니라 제한된 sequence와 최근 오류를 추적하는 규약입니다.',
      'Producer는 errseq_set, observer는 sample·check·check_and_advance를 사용합니다. 같은 since를 여러 thread가 변경할 때 외부 보호를 제공하며 오류 반환을 확인하고 counter wrap·여러 오류 합쳐짐의 한계를 이해합니다.',
      'errseq_check_and_advance의 READ_ONCE·ERRSEQ_SEEN cmpxchg·since 갱신·negative errno를 읽으세요.',
      q('한 observer가 오류를 확인하면 다른 observer의 since도 자동 변경되는가?','observer별 since는 별도로 관리된다','모든 열린 file의 오류가 동시에 지워진다','공유 error sequence와 각 observer의 관찰 지점은 다릅니다. 다른 observer는 자신의 sample 이후 변화를 확인할 수 있습니다.'),
      q('이 API가 매번 발생한 모든 오류를 무한 list로 반환하는가?','encoded sequence 규약이며 완전 event log가 아니다','항상 모든 발생 횟수와 원인을 보존한다','제한된 상태 표현과 wrap이 있습니다. Error monitoring 요구에 맞는 범위를 이해해야 합니다.'),
      details=[detail('Since 보호','Eseq의 atomic update가 caller의 since 변수 갱신 경쟁까지 해결하지 않습니다. 같은 관찰 지점을 공유하는 경우 해당 lock을 지켜야 합니다.'),detail('Writeback 연결','파일 쓰기 제출 뒤 IO 오류가 생겨도 이후 fsync 등 observer가 이를 전달해야 합니다. 로컬 write 성공과 뒤의 오류 관찰을 연결하는 예입니다.'),
        detail('Set를 끝까지 읽기','errseq_set은 0 또는 표현 범위 밖 errno를 경고하고 기존 값을 반환합니다. 허용 오류는 기존 error와 SEEN bit를 지우고 새 errno를 넣습니다. 이전 값에 SEEN이 있을 때만 counter를 올립니다. 같은 값이면 종료하고 cmpxchg가 경쟁으로 다른 값을 보았으면 그 값으로 다시 계산합니다. 반환값은 이후 sample로 쓰기 위한 API가 아닙니다.'),
        detail('Sample은 Seen을 쓰지 않는다','errseq_sample은 공유 값을 READ_ONCE로 읽고 SEEN이 없으면 0을 반환합니다. 아직 누구도 소비하지 않은 error가 새 observer에게도 이후 check에서 보이게 하기 위한 규약입니다. 이 함수 자체는 공유 SEEN을 설정하지 않습니다.'),
        detail('Check와 Advance 차이','errseq_check는 since와 같으면 0, 다르면 low error bits의 음수 errno를 반환하고 since를 변경하지 않습니다. Check_and_advance는 다르면 old|SEEN을 만들고 공유 값 CAS를 시도하며 결과를 기다려 재시도하지 않습니다. Observer since는 그 sampled new로 갱신하고 해당 error를 반환합니다.'),
        detail('숫자로 따라가기','MAX_ERRNO=4095인 구성은 error 12bit, SEEN=4096, counter 증가 단위=8192입니다. 초기 0에서 -EIO(5)를 set하면 5입니다. Sample은 unseen이므로 0, advance는 since=4101과 오류 -5를 반환합니다. 다음 -EIO set은 seen을 지우고 counter를 올려 8197이 되므로 같은 errno도 새 관찰 구간의 변화가 됩니다.'),
        detail('CAS 실패도 Reader가 진행하는 이유','Reader의 SEEN CAS가 실패하면 다른 writer가 상태를 바꾸었거나 다른 reader가 이미 SEEN을 붙였을 수 있습니다. 이 함수는 자신의 sample 기준 error를 반환하고 since를 진행하며 다음 check가 이후 변화를 볼 수 있게 합니다. 현재값 전체를 반드시 다시 읽어 가장 최신 error를 반환하는 함수로 설명하지 않습니다.'),
        detail('파일의 선언과 한계','errseq_t는 unsigned 32bit 표현이고 저비트 mask가 가능한지 BUILD_BUG_ON_NOT_POWER_OF_2로 검사합니다. Includes와 네 EXPORT_SYMBOL이 외부 caller를 연결합니다. 높은 counter도 유한하여 wrap 충돌이 가능하고 미관찰 기간의 여러 오류는 최신 오류로 합쳐질 수 있습니다.')])
    topic('Seq Buffer·고정 버퍼 출력과 Overflow','라이브러리·알고리즘','lib/seq_buf.c','seq_buf_vprintf',
      '커널 진단 문자열을 제한된 buffer에 이어 쓸 때 공간과 overflow를 일관된 상태로 추적해야 합니다.',
      'Seq_buf는 buffer·size·len을 관리하고 printf·put·hex 출력 등을 연결합니다. 남은 공간을 넘는 결과는 overflow 상태로 표시하며 자동 무한 확장을 하지 않습니다. Seq_file의 반복 출력 관리와 고정 buffer helper의 역할은 다릅니다.',
      'seq_buf_init 후 제한된 출력 helper를 사용하고 has_overflowed·str·len의 계약을 확인합니다. Format 인자 타입·NUL 공간·반환 오류를 검사하며 overflow된 결과를 완전한 보고서로 처리하지 않습니다.',
      'seq_buf_vprintf의 vsnprintf 반환 길이·남은 공간·seq_buf_set_overflow를 읽으세요.',
      q('Seq_buf 출력이 공간을 넘으면 buffer가 자동으로 계속 커지는가?','overflow 상태를 확인해야 한다','항상 새 page를 무한 할당한다','고정 buffer와 size로 동작합니다. Truncated 출력과 성공적인 전체 결과를 구분해야 합니다.'),
      q('vsnprintf의 필요 길이가 남은 공간보다 크면 len을 그대로 실제 기록 길이로 더해도 되는가?','필요 길이와 실제 공간·overflow를 구분한다','반환값은 항상 buffer 안의 byte 수다','snprintf 계열의 반환은 필요한 길이를 나타낼 수 있습니다. Helper의 검사와 overflow 표시를 따라야 합니다.'),
      details=[detail('Format 타입','가변 인자는 compiler가 runtime 타입을 자동 복구하지 않습니다. Pointer·정수 폭과 format이 맞아야 진단 값이 정확합니다.'),detail('NUL 종료','문자열 view를 얻는 helper의 종료 보장과 용량을 확인합니다. Binary put이나 raw buffer와 NUL 문자열을 무조건 동일하게 다루지 않습니다.')])
    topic('Base64·6비트 문자 인코딩','라이브러리·알고리즘','lib/base64.c','base64_encode',
      '임의 binary byte를 제한된 문자 집합으로 표현하려면 bit 묶음과 padding 규약을 알아야 합니다.',
      'Base64는 3byte의 24bit를 6bit 네 묶음으로 나눠 64문자 표에 대응합니다. 남은 1·2byte는 padding을 포함한 네 문자로 표현합니다. 인코딩은 가역적인 표현 변환이며 암호화·인증·압축이 아닙니다. 이 helper는 길이를 반환하고 NUL을 자동 추가하지 않습니다.',
      'Src 길이와 필요한 dst 공간을 미리 검증하고 반환 길이만큼 사용합니다. 표준 alphabet과 URL-safe 변형·padding 규약을 구분하며 decoder 오류와 외부 입력 크기를 검사합니다.',
      'base64_encode의 ac accumulator·bits-=6·0x3f·padding·반환 뒤 종료 byte 부재를 읽으세요.',
      q('입력 4byte를 표준 padding 포함 Base64로 표현한 길이는?','8문자','4문자','3byte는 4문자이고 남은 1byte도 padding을 포함한 4문자입니다. 4*ceil(4/3)=8입니다. C 문자열 NUL 공간은 별도로 필요할 수 있습니다.'),
      q('Base64 결과를 얻으면 그 안의 비밀값이 암호화되어 숨겨졌는가?','키 없이 되돌릴 수 있는 인코딩이다','문자가 달라졌으므로 기밀성이 보장된다','Base64는 표현 변환입니다. 비밀 보호·메시지 인증 기능을 제공하지 않습니다.'),
      details=[detail('출력 소유권','호출자가 dst를 준비하며 함수는 dstCapacity 인자를 받지 않습니다. 길이 계산과 buffer 확보가 caller의 책임입니다.'),detail('NUL과 Length','원본은 cp-dst를 반환하고 종료 NUL을 쓰지 않습니다. 반환 byte 수와 문자열 API가 요구하는 종료 byte를 구분합니다.'),
        detail('Encode 상태를 추적하기','매 byte마다 ac를 8bit 왼쪽으로 밀어 입력을 OR하고 bits에 8을 더합니다. 6bit씩 table index를 뽑은 뒤 남은 bit를 높은 쪽에 맞춰 마지막 문자를 쓰고 음수가 된 bits에 2씩 더하며 =을 씁니다. Table은 A-Z/a-z/0-9/+와 /이며 URL-safe -/_와 다릅니다.'),
        detail('Decode의 실제 검사','Decoder는 table에서 문자를 찾아 6bit를 누적하고 8bit가 모이면 출력합니다. =은 별도 branch로 accumulator와 bits만 진행하며 byte를 출력하지 않습니다. Table에 없는 문자와 NUL은 -1이고 마지막 남은 bit가 nonzero여도 -1입니다. 함수에 별도의 전체 padding 위치·총 입력 길이 multiple-of-4 검사 branch는 없습니다.'),
        detail('Canonical 검증과 Helper','이 decoder의 성공을 모든 표준 canonical 조건을 확인했다는 뜻으로 사용하지 않습니다. 실행 대조에서 padding 없는 TQ는 M을 반환하고 TR은 남은 bit가 nonzero라 -1이지만, TR==는 padding branch가 accumulator를 이동시켜 M을 반환했습니다. Padding-only ====도 길이 0으로 성공했습니다. 따라서 성공을 canonical 형식 보증으로 쓰지 말고 protocol의 엄격한 입력 policy를 별도로 확인합니다.'),
        detail('전체 파일의 계약','파일은 alphabet table·두 함수·두 GPL export와 includes로 구성됩니다. 두 함수 모두 dst capacity 인자가 없어 caller가 공간과 입력 길이를 검증해야 합니다. Decoder는 오류까지 이미 일부 byte를 썼을 수도 있어 실패 출력을 정상 data로 소비하지 않습니다.')])
    topic('ASN.1 BER·길이와 상태 기계','라이브러리·알고리즘','lib/asn1_decoder.c','asn1_ber_decoder',
      '서명·인증서 등의 구조화된 binary 입력을 해석할 때 tag·length·중첩과 parser program을 검증해야 합니다.',
      'ASN.1 BER decoder는 생성된 opcode machine·actions를 실행하면서 data pointer와 tag·length·constructed stack·jump stack을 관리합니다. Indefinite length와 end-of-content 처리도 존재하지만 모든 ASN.1 규칙을 무제한 일반 interpreter로 지원하는 것은 아닙니다.',
      '해당 grammar로 생성한 decoder와 action callback을 사용하고 입력 길이·tag·중첩·오류를 검사합니다. BER 허용 형식과 서명 규약의 DER canonical 요구를 구분하며 parse 성공을 인증서 신뢰 검증으로 간주하지 않습니다.',
      'asn1_ber_decoder의 datalen·machine pc·data dp·constructed/jump stack과 error 경로를 읽으세요.',
      q('v6.12 이 decoder에 datalen=70000을 주면 시작 검사 결과는?','-EMSGSIZE','길이를 16bit로 잘라 계속한다','원본은 datalen>65535를 거부합니다. 지원 범위보다 큰 입력을 truncation하여 다른 메시지로 해석하지 않습니다.'),
      q('ASN.1 parse에 성공하면 해당 인증서가 신뢰할 issuer에게 서명되었음도 확정되는가?','구문 해석과 암호·신뢰 검사는 별도다','Tag가 맞으면 모든 서명이 유효하다','Parser는 구조를 읽습니다. Signature·키·chain·정책 검사는 다른 단계입니다.'),
      details=[detail('유한 Stack','Constructed와 jump stack은 이 코드에서 각각 10개로 선언됩니다. 깊이·machine 흐름 검사를 통해 준비한 저장 공간을 넘어가지 않아야 합니다.'),detail('길이 검증','Length field를 읽는 것만으로 payload가 실제 buffer 안에 있다는 뜻이 아닙니다. 남은 입력·부모 constructed 범위·overflow를 함께 확인합니다.')])
    topic('Glob·와일드카드와 재시도','라이브러리·알고리즘','lib/glob.c','glob_match',
      'Trace 필터 등에서 간단한 pattern을 비교할 때 wildcard와 regular expression·경로 matching을 구분해야 합니다.',
      'glob_match는 문자·?·*·문자 class 등을 해석하고 mismatch 때 이전 * 위치로 돌아가 string 시작을 한 문자 늘려 다시 시도합니다. *는 /도 예외 없이 매치하고 ?는 NUL을 제외한 한 문자를 처리합니다. 구현은 마지막 star의 재시도 위치로 동작합니다.',
      '해당 kernel helper의 pattern 문법과 byte 문자열 규약을 따릅니다. Shell glob의 경로·dotfile 규칙이나 모든 regex 문법을 가져오지 않고 filter 입력·실행 비용·escape를 확인합니다.',
      'glob_match의 back_pat·back_str·?·*·class·mismatch 재시도를 읽으세요.',
      q('이 helper에서 pattern a*b는 문자열 a/x/b와 매치할 수 있는가?','*가 /를 포함해 매치할 수 있다','*는 모든 /에서 반드시 중단된다','파일 시작 설명과 구현은 *가 /를 예외 처리하지 않는다고 명시합니다. Shell의 pathname glob 규칙과 혼동하지 않습니다.'),
      q('Pattern ? 하나가 빈 문자열과 매치하는가?','NUL을 제외한 한 문자라 매치하지 않는다','?는 항상 0개 문자도 허용한다','case ?는 c==NUL이면 false를 반환합니다. 0개 이상을 뜻하는 *와 다릅니다.'),
      details=[detail('Star 재시도','*에서 pattern의 다음 위치와 string 현재 위치를 보관합니다. 뒤쪽 token이 실패하면 string 후보를 하나씩 전진해 다시 비교합니다.'),detail('Regex와 구분','괄호·+ 등 regex 문법이 자동으로 지원되는 것은 아닙니다. 해당 byte pattern의 character class·escape·literal 계약을 직접 확인합니다.')])
    topic('Packing·Bitfield와 Endian Quirk','라이브러리·알고리즘','lib/packing.c','packing',
      '장치 protocol의 bit 배치가 CPU endian이나 C bitfield 배치와 다를 때 명시적으로 값을 넣고 꺼내야 합니다.',
      'Packing은 logical startbit·endbit 범위를 byte buffer에 연결하고 PACK/UNPACK과 endian·bit order quirk를 적용합니다. 폭은 start-end+1이며 u64를 넘을 수 없습니다. C struct의 compiler bitfield layout을 hardware wire format과 그대로 같다고 가정하지 않습니다.',
      'Hardware 문서의 logical bit 번호·buffer 길이·quirks를 맞춰 API를 사용합니다. PACK 값이 폭에 들어가는지·start≥end·범위를 검사하고 결과 오류를 처리합니다.',
      'packing의 value_width·range 검사와 QUIRK별 logical byte 변환을 읽으세요.',
      q('Startbit=7, endbit=4의 field 폭과 들어갈 수 있는 최대 unsigned 값은?','4bit, 15','3bit, 16','폭=7-4+1=4입니다. 4bit unsigned 값은 0..15이고 16은 넘칩니다. 원본은 맞지 않는 PACK 값을 -ERANGE로 거부합니다.'),
      q('startbit<endbit이면 이 함수는?','-EINVAL','두 index를 자동으로 바꾼다','API는 startbit가 더 큰 논리 번호인 계약입니다. 원본은 잘못된 순서를 거부하며 caller 오류를 숨기지 않습니다.'),
      details=[detail('64bit Shift','폭이 64일 때 1ull<<64를 사용하면 C에서 유효한 shift가 아닙니다. 원본은 value_width<64 조건에서만 이 범위 검사를 수행합니다.'),detail('Bit과 Byte','Bit 번호 반전·byte endian·32bit word 순서 등의 quirk는 다른 축입니다. 하나의 endian toggle로 모든 hardware 배치를 설명하지 않습니다.')])
    topic('Argv Split·공백 기반 Token','라이브러리·알고리즘','lib/argv_split.c','argv_split',
      '간단한 인자 문자열을 pointer 배열로 나누면서 복사한 문자열 저장소의 소유권도 유지해야 합니다.',
      'Argv_split은 문자열을 복제하고 isspace 경계에서 NUL을 넣어 token pointer 배열을 만듭니다. 연속 공백을 건너뛰고 마지막 argv는 NULL입니다. Shell quoting·변수 확장·명령 실행 parser가 아니며 반환 배열 앞에 backing string pointer를 관리합니다.',
      '단순 공백 token 문법이 적합할 때만 사용하고 allocation 실패 NULL을 검사합니다. argv_free로 backing storage와 배열을 함께 정리하며 개별 token을 각각 kfree하지 않습니다.',
      'argv_split의 kstrndup·argc+2·argv_ret=++argv·was_space와 argv_free를 읽으세요.',
      q('문자열 a 공백 공백 b를 나누면 빈 token이 공백마다 생성되는가?','a와 b 두 token으로 나뉜다','a·빈 token·b 세 token이다','was_space는 연속 공백을 하나의 경계로 처리합니다. 새 non-space 구간에서만 argv pointer를 추가합니다.'),
      q('따옴표로 감싼 hello world를 shell처럼 하나의 인자로 자동 해석하는가?','따옴표 shell 규칙은 제공하지 않는다','모든 shell escape와 변수 치환을 수행한다','단순 isspace 기반 splitting입니다. 따옴표 byte는 shell parser처럼 공백을 보호하지 않습니다.'),
      details=[detail('공유 저장소','각 token pointer는 복제된 같은 문자열 내부를 가리킵니다. 한 token을 별도 allocation처럼 해제하면 allocator 규칙을 깨뜨립니다.'),detail('종료 Pointer','argv의 마지막 NULL과 각 token의 NUL은 서로 다른 종료 방식입니다. Argc와 배열 sentinel·backing 저장 위치를 구분합니다.'),
        detail('Count를 한 줄씩 읽기','count_argc는 was_space=true로 시작하고 공백이면 true를 유지하며 새로운 non-space run 시작에서만 count를 올립니다. 빈 문자열과 공백-only는 0, 앞뒤 공백과 연속 공백은 빈 token을 만들지 않습니다.'),
        detail('왜 argc+2인가','Pointer 배열 첫 칸은 backing 문자열 원래 주소, 뒤 argc칸은 token, 마지막 한 칸은 NULL sentinel입니다. Caller에 반환하는 argv_ret는 첫 숨겨진 칸을 지나 ++argv입니다. Empty 입력도 backing 저장칸과 sentinel이 필요합니다.'),
        detail('문자열 복사와 실패','kstrndup으로 local copy를 만들고 그 복사본에서 count와 splitting을 합니다. 원래 sysctl 문자열이 바뀌는 상황에서 두 단계가 서로 다른 문자열을 읽는 문제를 줄입니다. Pointer 배열 allocation 실패면 backing 문자열을 free한 뒤 NULL입니다. Optional argcp가 non-NULL이면 count를 기록합니다.'),
        detail('Free를 한 줄씩 읽기','argv_free는 전달받은 pointer를 한 칸 뒤로 이동하고 argv[0]의 원래 문자열 allocation을 kfree한 다음 배열도 kfree합니다. 매 token의 중간 주소를 별도로 free하는 함수가 아닙니다. NULL을 그냥 넘겨도 안전하다는 branch가 없으므로 split 실패와 ownership을 caller가 구분합니다.'),
        detail('파일 전체','파일의 count_argc·argv_split·argv_free와 includes·두 EXPORT_SYMBOL을 연결합니다. 복사한 문자열에 공백 NUL을 쓰면서 caller 원본은 직접 바꾸지 않고, 따옴표·escape·환경 변수의 shell 해석도 수행하지 않습니다.')])
    topic('Kstrtox·기수와 오버플로','라이브러리·알고리즘','lib/kstrtox.c','kstrtouint',
      'Kernel 설정 문자열을 숫자로 변환할 때 잘못된 suffix·음수·폭 초과를 조용히 받아들이면 안 됩니다.',
      'Kstrto 계열은 문자열과 base를 검사하며 성공 0 또는 -EINVAL/-ERANGE 등을 반환합니다. Base 0은 0x prefix를 16진수, 앞선 0을 8진수, 나머지를 10진수로 해석합니다. Kstrtouint는 넓은 temporary 값이 unsigned int로 변환해도 같은지 비교해 축소 overflow를 검사합니다.',
      '정해진 숫자 형식에 맞는 signed/unsigned API와 base를 선택하고 return을 검사한 뒤 output을 사용합니다. 단일 마지막 newline 허용과 trailing garbage 규약을 확인하며 오류 때 output이 유효하다고 가정하지 않습니다.',
      'kstrtouint의 kstrtoull·tmp cast 비교와 _kstrtoull의 종료 문자를 읽으세요.',
      q('Base 0으로 문자열 010을 읽으면 unsigned 값은?','8','10','선행 0 때문에 8진수입니다. 010=1*8+0=8이며 십진수 문법을 원하면 base 10을 명시해야 합니다.'),
      q('넓은 tmp가 unsigned int 변환 후 달라지면?','-ERANGE','잘린 값을 무조건 성공으로 쓴다','원본은 tmp!=(unsigned int)tmp이면 거부합니다. 유효 입력이 작은 목적 타입으로 들어가는지 별도로 검사합니다.'),
      details=[detail('Signed 선택','음수가 허용되는 정책과 unsigned ID는 다른 입력입니다. 함수 선택과 base·허용 범위를 목적에 맞춰야 합니다.'),detail('반환과 Output','에러 code를 확인하지 않고 res를 쓰면 이전 값·초기화되지 않은 값을 설정에 적용할 수 있습니다. 성공일 때만 결과를 소비합니다.')])
    topic('Linear Range·수치와 Selector 변환','라이브러리·알고리즘','lib/linear_ranges.c','linear_range_get_selector_low',
      'Regulator 등의 register selector를 실제 전압·수치 범위와 연결할 때 구간별 선형식을 관리할 수 있습니다.',
      'Linear range는 최소 값·selector 최소/최대·step을 담습니다. 값=min+(selector-min_sel)*step이며 low selector는 원하는 값 이하의 범위 위치를 정수 나눗셈으로 찾습니다. Step 0은 고정 값 구간이고 반환 코드와 found flag가 서로 다른 정보를 줍니다.',
      '지원 hardware 범위의 단위를 맞추고 low/high/within API 차이를 선택합니다. Range 밖·step 0·overflow·found flag를 처리하며 반올림 방향이 제한 조건에 맞는지 확인합니다.',
      'linear_range_get_selector_low의 min 검사·max 초과·found·step 0 분기를 읽으세요.',
      q('min=100, min_sel=2, step=25이며 범위 안 val=164이면 low selector와 대응 값은?','selector 4, 값 150','selector 5, 값 175','(164-100)/25는 정수 나눗셈 2입니다. 2+2=4이고 100+(4-2)*25=150입니다. 175는 요청보다 높은 방향입니다.'),
      q('Val가 해당 range 최대 값보다 크면 low helper의 반환·found는?','0과 found=false이며 max_sel을 줄 수 있다','무조건 0이면 요청이 범위 안이다','원본은 최대를 넘으면 max_sel을 쓰고 found=false인 채 0을 반환합니다. Errno 성공과 범위 포함 여부를 구분합니다.'),
      details=[detail('Low와 High','전압 최소 요구를 충족하려면 아래로 내림한 값이 부적합할 수 있습니다. 요청 정책에 맞는 올림·내림·구간 API를 선택합니다.'),detail('고정 값','step=0인 구간은 나눗셈을 하지 않고 min_sel을 사용합니다. 선형식을 그대로 division에 적용하면 0으로 나누게 됩니다.')])
    topic('BCH·유한체 오류 정정','라이브러리·알고리즘','lib/bch.c','bch_encode',
      'Flash 등의 제한된 bit 오류를 정정하려면 data뿐 아니라 code의 parity와 유한체 계산이 필요합니다.',
      'Binary BCH code는 GF(2^m)의 다항식 구조로 parity를 만들고 syndrome·오류 locator 등을 통해 정정 위치를 구합니다. Linux encoder는 generator 관련 table로 word·byte 처리를 가속합니다. M·t·data 길이·bit ordering에 따른 code 규약과 최대 정정 능력을 맞춰야 합니다.',
      'BCH control을 초기화하고 ecc 길이·raw data·stored parity 규약을 맞춥니다. Decode가 주는 bit 위치와 실패를 검사하고 caller가 data를 수정합니다. CRC처럼 탐지만 하는 코드와 구분하며 t를 넘은 오류의 정정을 보장하지 않습니다.',
      'bch_encode의 ecc_buf 초기화·mod8_tab·unaligned byte 처리와 bch_decode를 읽으세요.',
      q('BCH 설계 정정 능력이 t라면 t보다 많은 bit 오류도 반드시 정확히 고치는가?','정정 보장 범위를 넘는다','parity가 있으면 오류 수에 제한이 없다','Code의 distance와 decoder 능력에는 한계가 있습니다. 검출 실패·decode 실패·잘못된 정정 가능성을 요구 조건에 맞춰 다룹니다.'),
      q('bch_encode에서 ecc pointer를 NULL로 주면 초기 내부 parity는?','ecc_buf를 0으로 초기화한다','존재하지 않는 ecc를 읽는다','원본은 ecc가 있으면 parity를 load하고 없으면 내부 buffer를 memset합니다. 이어 계산 규약과 최초 계산을 구분합니다.'),
      details=[detail('GF 덧셈','Binary extension field의 덧셈은 XOR입니다. 곱셈·나머지는 지정 polynomial에 따른 연산이므로 일반 정수 곱셈과 다릅니다.'),detail('ECC Layout','장치의 stored ECC byte 순서와 bit numbering이 decoder 입력과 맞아야 합니다. 수학적으로 같은 code라도 표현이 다르면 정정 위치를 잘못 적용할 수 있습니다.')])
    topic('Reed-Solomon·Parity와 Symbol 오류','라이브러리·알고리즘','lib/reed_solomon/reed_solomon.c','encode_rs8',
      'Byte 등 여러 bit를 묶은 symbol의 오류를 정정하려면 bit 오류 개수와 symbol 오류 개수를 구분해야 합니다.',
      'Reed-Solomon code는 GF(2^m) symbol과 generator polynomial로 parity를 계산합니다. Kernel encoder template는 feedback을 log/antilog table로 곱하고 parity register를 이동합니다. Nroots parity symbol은 일반적인 조건에서 2e+v≤nroots인 error e·알려진 erasure v 범위를 다룹니다.',
      'RS control의 symbol 폭·field polynomial·first root·primitive step·nroots를 송수신 양쪽에서 맞춥니다. Shortened code 길이·parity 초기화·invmsk·decode 위치와 실패를 처리하며 RS8 data 폭과 parity 저장 타입을 구분합니다.',
      'encode_rs8의 include encode_rs.c와 template의 pad·feedback·parity shift를 읽으세요.',
      q('Parity가 8symbol이고 알려진 erasure가 없을 때 일반적 오류 정정 능력은?','최대 4symbol 오류','항상 8symbol 오류','2e+v≤8이고 v=0이면 e≤4입니다. 한 symbol 안의 여러 bit 오류를 하나의 symbol 오류로 세는 code 규약입니다.'),
      q('8 parity symbol에서 알려진 erasure 2개와 오류 3개는 능력 조건에 들어가는가?','2*3+2=8로 조건 안이다','3+2를 byte 길이로만 세면 된다','Error 위치를 모르는 경우와 erasure 위치를 아는 경우의 비용이 다릅니다. Code parameter와 decoder 계약이 맞는 예입니다.'),
      details=[detail('Shortening','Template는 pad=nn-nroots-len을 검사해 유효 data 길이를 제한합니다. Full code 길이와 실제 짧은 메시지 길이를 구분합니다.'),detail('Table 표현','index_of는 field element를 지수 표현으로, alpha_to는 지수를 element로 연결합니다. Feedback의 zero sentinel과 modnn 처리도 일반 modulo integer와 다릅니다.')])
    topic('LZ4·Literal와 Match Token','라이브러리·알고리즘','lib/lz4/lz4_decompress.c','LZ4_decompress_safe',
      '반복 문자열을 이전 출력 위치의 참조로 표현하면 빠르게 압축·해제할 수 있지만 입력·출력 경계를 검증해야 합니다.',
      'LZ4 block의 token은 literal와 match 길이 정보를 담고 확장 byte·offset으로 이전 출력의 반복을 표현합니다. Match 복사는 겹칠 수 있어 일반 memcpy와 계약이 다릅니다. Safe decoder는 compressedSize·output capacity와 입력 끝을 기준으로 검증합니다.',
      'Block과 frame format·dictionary를 구분하고 압축 길이·최대 출력 공간을 검증한 safe API를 사용합니다. 음수 오류와 복원 길이를 확인하고 압축 data가 신뢰된 원본이라는 이유로 bounds 검사를 생략하지 않습니다.',
      'LZ4_decompress_safe가 generic에 endOnInputSize·decode_full_block·noDict를 넘기는 경로를 읽으세요.',
      q('Match offset=1이고 길이=4이면 이전 한 byte를 반복할 수 있는가?','겹치는 복사 규약으로 반복을 만들 수 있다','모든 match는 복사 구간이 절대 겹치지 않는다','LZ 계열 back-reference는 이미 생성 중인 출력이 다음 복사의 원본이 될 수 있습니다. Decoder는 overlap을 지원하는 방식으로 진행해야 합니다.'),
      q('Safe decoder에서 maxDecompressedSize는?','목적 buffer에 쓸 수 있는 최대 크기','입력 압축률의 percent','출력 capacity입니다. 압축 길이가 작아도 확장 결과는 클 수 있으므로 두 길이를 모두 검증합니다.'),
      details=[detail('Literal','이전 참조로 표현하지 않은 raw byte 구간입니다. Token 길이를 읽은 뒤 실제 남은 input·output 공간을 확인해야 합니다.'),detail('Frame과 Block','LZ4 block helper는 frame header·checksum 등 외부 container의 전체 기능과 다릅니다. 저장소가 어떤 형식을 사용했는지 먼저 확인합니다.')])
    topic('LZO·짧은 Match와 스트림','라이브러리·알고리즘','lib/lzo/lzo1x_compress.c','lzo1x_1_compress',
      '빠른 해제를 중시하는 압축에서 literal run과 여러 길이·거리 match 표현의 비용을 조정할 수 있습니다.',
      'LZO1X는 literal와 이전 data의 match를 compact byte 규칙으로 인코딩합니다. Compressor는 working dictionary로 후보를 찾고 decoder는 길이·offset과 종료 표식을 해석합니다. LZO-RLE 변형은 zero run 등의 별도 지원을 가지며 format과 version을 맞춰야 합니다.',
      'Kernel LZO API의 worst-case 출력 크기·workmem 크기를 준비하고 반환과 실제 out_len을 검사합니다. 해제는 input/output 범위를 검사하는 safe API를 사용하며 LZO와 LZO-RLE를 이름만 같다고 섞지 않습니다.',
      'lzo1x_1_compress와 lzorle1x_1_compress의 generic version 인자, lzo1x_decompress_safe를 비교하세요.',
      q('압축 결과가 언제나 입력보다 작아지는가?','비반복 data는 overhead로 커질 수 있다','모든 입력은 반드시 절반 크기다','Literal·header·종료 표식 등 표현 비용이 있습니다. Worst-case 공간을 준비하고 압축을 저장할지 정책으로 선택해야 합니다.'),
      q('LZO와 LZO-RLE wrapper가 generic에 같은 version 인자를 넘기는가?','0과 LZO_VERSION을 구분한다','두 wrapper는 완전히 같은 호출이다','원본은 일반 LZO에 0, RLE wrapper에 LZO_VERSION을 넘깁니다. 형식 차이는 decoder 선택·저장 규약과 연결됩니다.'),
      details=[detail('Workmem','후보 dictionary 등 compressor 임시 상태에 필요한 공간입니다. 출력 buffer와 서로 다른 역할이며 concurrency 규약을 따릅니다.'),detail('안전한 해제','Offset이 이미 출력된 범위를 넘어가거나 입력 길이가 부족하면 거부해야 합니다. 압축된 몇 byte가 큰 출력으로 확장될 수 있음을 고려합니다.')])
    topic('Deflate·LZ77와 Huffman','라이브러리·알고리즘','lib/zlib_deflate/deflate.c','zlib_deflate',
      '반복 참조를 만든 뒤 token 빈도도 줄여 표현하려면 사전 압축과 entropy coding을 결합할 수 있습니다.',
      'Deflate는 literal·length/distance의 LZ77 표현과 Huffman code를 사용합니다. Stored·fixed·dynamic block을 구분하고 zlib stream 상태는 input/output 잔량과 flush mode를 관리합니다. Deflate raw bitstream·zlib wrapper·gzip container는 서로 다른 층입니다.',
      'Kernel zlib workspace·init·deflate·end 계약을 따르고 next_in/out·avail_in/out을 갱신합니다. Z_OK·Z_STREAM_END·Z_BUF_ERROR 등을 구분하며 한번 호출이 전체 압축 완료를 뜻한다고 가정하지 않습니다.',
      'zlib_deflate의 flush 범위·FINISH_STATE·avail_out==0 검사와 block 출력 경로를 읽으세요.',
      q('zlib_deflate를 호출했는데 avail_out이 0이면 초기 반환은?','Z_BUF_ERROR','출력 공간 없이 무조건 완료','원본은 avail_out==0이면 buffer 오류를 반환합니다. 추가 공간과 상태 규약을 준비해야 합니다.'),
      q('Deflate bitstream과 gzip 파일은 모든 byte가 같은가?','container header·trailer 층을 구분한다','압축 algorithm 이름이 같으면 header도 같다','Gzip과 zlib wrapper는 별도 framing·검사 값을 가집니다. Raw Deflate decoder와 container parser의 역할을 맞춰야 합니다.'),
      details=[detail('Huffman','자주 나온 token에 짧은 code를 배정해 symbol 비용을 줄입니다. Dynamic block은 code tree를 설명하는 overhead가 있어 짧은 입력에서 항상 이득은 아닙니다.'),detail('Flush','중간 data를 내보내는 요구와 마지막 stream 종료는 다릅니다. Finish 상태 이후 허용 mode와 output 부족 시 재호출을 관리합니다.')])
    topic('XZ·Range Coding과 Dictionary','라이브러리·알고리즘','lib/xz/xz_dec_lzma2.c','xz_dec_lzma2_run',
      '작은 압축 크기를 얻는 format은 큰 dictionary·상태 모델 비용을 가질 수 있어 decoder 자원을 먼저 제한해야 합니다.',
      'XZ container는 block·filter·check를 관리하고 LZMA2는 compressed/uncompressed chunk와 dictionary·properties·state reset 규칙을 담습니다. LZMA의 반복·literal probability model은 range coding과 연결됩니다. Container와 LZMA2 chunk 상태 기계를 분리해 읽습니다.',
      'XZ decoder mode와 memory limit·input/output position을 초기화하고 반환 상태에 따라 재호출·오류·종료를 처리합니다. Filter 지원과 checksum·dictionary reset을 확인하며 비신뢰 header의 dictionary 요구를 무제한 할당하지 않습니다.',
      'xz_dec_lzma2_run의 SEQ_CONTROL·0x00/0x01/0x02·compressed control의 reset 조건을 읽으세요.',
      q('LZMA2 control byte 0x00의 역할은?','end marker','항상 dictionary 크기를 두 배로 만든다','원본의 control 설명은 0x00을 종료 표식으로 정의합니다. Stream 종료와 단순 input buffer 소진을 구분합니다.'),
      q('LZMA2의 uncompressed chunk는 존재할 수 없는가?','0x01·0x02 등의 uncompressed 경로가 있다','모든 chunk는 반드시 entropy 압축이다','Format은 비압축 chunk도 지원합니다. 압축률이 나쁜 data와 reset 조건을 해당 상태 기계에 따라 해석합니다.'),
      details=[detail('Reset','Dictionary·properties·model state는 별도 reset 조건입니다. 앞선 dictionary가 유효하지 않은 stream 시작에서 reset 없이 match를 참조하면 잘못된 출력이 됩니다.'),detail('스트리밍','Input chunk 경계와 압축 block 경계는 같지 않을 수 있습니다. Decoder state와 in_pos/out_pos를 유지하며 다음 buffer로 이어갑니다.')])
    topic('Zstd·반복과 Entropy 부호화','라이브러리·알고리즘','lib/zstd/decompress/zstd_decompress.c','ZSTD_decompressDCtx',
      '압축 성능·해제 속도·dictionary 재사용을 조절하려면 literal와 sequence coding을 구분해야 합니다.',
      'Zstd는 frame과 block에서 literal·match sequence를 표현하고 Huffman·FSE 등의 entropy coding을 사용합니다. Window·dictionary·repeated offset·checksum 조건을 해석하며 raw/RLE/compressed block이 존재합니다. Context는 재사용할 상태와 dictionary 연결을 관리합니다.',
      'Kernel zstd wrapper의 workspace·context·지원 API를 우선 사용하고 입력 길이·destination capacity·window limit을 검증합니다. size_t 반환의 ZSTD_isError 규약을 확인하고 모든 양수 반환을 성공 출력 길이로 판단하지 않습니다.',
      'ZSTD_decompressDCtx의 usingDDict 연결과 kernel zstd wrapper·error helper를 읽으세요.',
      q('Zstd API의 size_t 반환이므로 오류는 절대 나타나지 않는가?','ZSTD_isError로 encoded error를 검사한다','모든 unsigned 값은 복원 길이다','오류를 size_t 영역의 특별한 값으로 표현할 수 있습니다. 먼저 error 여부를 확인한 뒤 output 길이로 사용해야 합니다.'),
      q('Dictionary로 압축한 data를 다른 dictionary로 무조건 같은 결과로 해제할 수 있는가?','frame·dictionary 식별과 계약을 맞춘다','dictionary는 성능 hint일 뿐 항상 무시 가능하다','압축 sequence나 entropy 상태가 dictionary에 의존할 수 있습니다. 필요한 dictionary 없이 동일 결과를 보장하지 않습니다.'),
      details=[detail('FSE','Finite State Entropy는 symbol probability에 따른 상태 전이와 bit 사용으로 정보를 표현하는 entropy coding 계열입니다. LZ match 탐색과 다른 압축 단계입니다.'),detail('자원 한도','Frame이 주장하는 길이·window와 실제 output capacity·지원 조건을 따로 확인합니다. 작은 입력이 무한한 memory 사용 권한을 뜻하지 않습니다.')])
    topic('842·템플릿 기반 압축','라이브러리·알고리즘','lib/842/842_compress.c','sw842_compress',
      '고정 크기 조각을 dictionary 참조와 raw 조각의 조합으로 압축하는 방식도 kernel에서 사용됩니다.',
      '842는 8·4·2byte data 조각의 이전 위치 참조를 template 조합으로 표현합니다. Compressor는 각 크기의 hash table 후보와 반복·zero 같은 특수 표현을 선택하고 bit output·CRC를 관리합니다. 이름의 숫자는 단순 압축률이 아니라 조각 표현과 연결됩니다.',
      'sw842 API의 workmem·olen 입력 capacity·출력 길이·strict mode 조건을 맞춥니다. Decoder의 오류·checksum·입출력 한도를 검사하며 hardware 842 지원과 software fallback 성능을 구분합니다.',
      'sw842_compress의 8/4/2 hash 초기화·p->olen·strict ilen%8 검사를 읽으세요.',
      q('Strict mode에서 ilen이 10byte이면 초기 길이 조건은?','8의 배수가 아니므로 -EINVAL','항상 10byte를 몰래 16byte로 확장한다','원본은 sw842_strict && ilen%8일 때 거부합니다. Mode별 입력 조건을 지켜야 합니다.'),
      q('olen pointer는 호출 전에 의미가 없는 output-only 값인가?','처음에는 output capacity를 제공하고 결과 길이를 받는다','초기 값은 무조건 읽지 않는다','원본은 *olen을 p->olen과 total에 보관한 뒤 *olen=0으로 초기화합니다. 입력 capacity와 결과 길이의 두 역할을 확인합니다.'),
      details=[detail('Template','Raw 조각과 dictionary index 조합에 따라 필요한 bit 수가 다릅니다. Match가 있다고 무조건 최단 template가 되는 것은 아니므로 후보와 비용을 비교합니다.'),detail('CRC','손상 탐지는 암호 인증과 다릅니다. Compressor/decoder가 검사 값을 사용해도 악의적 변경에 대한 MAC 보장을 제공하는 것은 아닙니다.')])
    topic('Window Minmax·제한된 시간의 극값','라이브러리·알고리즘','lib/win_minmax.c','minmax_running_max',
      '최근 RTT·대역폭의 극값을 전체 이력 없이 일정한 저장 공간으로 추적할 수 있습니다.',
      'Nichols의 windowed min/max tracker는 값·시간을 가진 후보 세 개를 유지하고 새 극값이나 만료에 따라 reset·shift·subwindow 후보를 갱신합니다. Update 시간·공간은 상수지만 모든 입력에서 정확한 전체 window 극값과 같다고 보장하는 저장 구조는 아닙니다.',
      'minmax를 초기화하고 같은 시간 단위의 monotonic sample·window와 max/min helper를 사용합니다. Timestamp wrap 조건과 비교 규약을 확인하며 정확한 전체 window가 필요한 요구에 무조건 대체하지 않습니다.',
      'minmax_running_max의 new max·third sample 만료·minmax_subwin_update를 읽으세요.',
      q('기존 최대보다 크거나 같은 새 sample이면?','새 sample로 후보를 reset할 수 있다','새 값은 오래된 최소로만 저장한다','원본은 val.v>=s[0].v이면 minmax_reset합니다. 더 최근의 같거나 큰 극값은 앞선 후보보다 유리합니다.'),
      q('후보 세 개만 저장하므로 모든 이력의 정확한 window 극값을 언제나 보장하는가?','상수 공간 근사 tracker의 한계를 구분한다','전체 이력을 완벽하게 복원한다','파일 설명은 almost always 같은 결과를 준다고 표현합니다. 세 후보만으로 arbitrary 전체 이력과 동일하다는 보장은 하지 않습니다.'),
      details=[detail('Subwindow','새 극값이 오래 없으면 window의 1/4·1/2 이후에 뒤 후보를 수집해 시간이 퍼지도록 합니다. 극값 후보와 단순 최근 sample 세 개는 다릅니다.'),detail('Max와 Min','비교 방향만 반대인 대응 경로가 있습니다. BBR 등의 모델이 어떤 값·단위·시간 window를 넣는지 연결해 읽습니다.'),
        detail('새 후보 비교','Max에서 새 값>=첫 후보이거나 마지막 후보도 window를 벗어나면 전체 reset입니다. 그렇지 않고 두 번째보다 크거나 같으면 뒤 두 후보를 새 값으로, 세 번째보다 크거나 같으면 마지막만 바꿉니다. Min은 <=로 대칭이며 같은 값이면 더 최근 sample이 유리합니다.'),
        detail('만료 후보 이동','dt>win이면 두 번째를 첫 번째로, 세 번째를 두 번째로 올리고 새 sample을 마지막에 넣습니다. 새 첫 후보도 만료되면 한 번 더 이동합니다. 전체 이력을 scan하는 loop가 아니라 제한된 두 번의 shift입니다.'),
        detail('시간을 퍼뜨리기','아직 두 후보의 시간이 같고 dt>win/4이면 뒤 둘을 새 sample로 교체합니다. 그렇지 않고 뒤 둘 시간이 같고 dt>win/2이면 마지막만 교체합니다. Else-if 순서가 있고 비교는 >이므로 정확한 경계값도 구분합니다.'),
        detail('작은 실행 표','Window=8에서 reset (t=0,v=100), 다음 (3,90)은 뒤 두 후보를 90@3으로, (5,80)은 마지막을 80@5로 바꿉니다. (9,70)은 첫 후보 100@0이 만료되어 90@3을 첫 후보로 올립니다. 반환 최대가 100에서 90으로 바뀌는 과정입니다.'),
        detail('Header 구조와 초기화','minmax_sample은 u32 t/v 두 field, minmax는 sample 세 개 배열입니다. minmax_get은 첫 v를 반환하고 minmax_reset은 같은 sample을 세 칸에 대입합니다. Header의 include guard·types include·두 running 함수 prototype이 C 파일의 정의를 연결합니다.'),
        detail('전체 파일 범위','C 파일은 subwindow helper와 running_max/min 세 함수·설명 주석·includes·max export로 구성됩니다. Timestamp 차는 unsigned u32이므로 wrap 및 지나간 시간의 해석 가능 범위를 caller가 지켜야 합니다. 값·시간의 단위와 monotonic 진행은 별도 호출 계약입니다.')])
    topic('PerCPU Counter·근사와 정확한 합','라이브러리·알고리즘','lib/percpu_counter.c','percpu_counter_add_batch',
      '자주 갱신되는 전체 count를 매번 global lock으로 수정하면 CPU 사이 cache 경합이 커집니다.',
      'PerCPU counter는 각 CPU의 작은 변화와 global count를 나눠 저장합니다. Batch 기준을 넘으면 local 잔량과 새 변화량을 global에 합치고 local을 조정합니다. 빠른 read는 잔량을 포함하지 않는 근사이고 sum은 CPU 잔량을 순회하는 더 정확하고 비싼 경로입니다.',
      '초기화·add·read·sum·destroy API와 caller context를 따릅니다. Exact 동시 snapshot 요구는 별도로 검토하고 hotplug의 dying CPU fold·batch 오차·정수 범위를 확인합니다. Check와 add를 나눠서 엄격 한도를 보장하려 하지 않습니다.',
      'percpu_counter_add_batch의 두 CONFIG 구현과 __percpu_counter_sum의 online|dying mask를 읽으세요.',
      q('Global count 100, 두 local 잔량이 +3·+4인 예에서 잔량 포함 합은?','107','100','100+3+4=107입니다. 빠른 global read와 모든 local을 합친 값을 구분해야 합니다. 동시 변경이 없는 단순 예입니다.'),
      q('CPU offline 중 합산이 online CPU만 읽어도 언제나 안전한가?','dying CPU의 미합산 잔량도 고려한다','offline 시작 순간 local 값은 자동 0이다','원본 sum은 online|dying mask를 사용합니다. Dying CPU가 global에 fold되기 전의 잔량을 빠뜨리지 않기 위한 조건입니다.'),
      details=[detail('IRQ 경합','Local 판단과 실제 업데이트 사이 interrupt가 count를 바꿀 수 있습니다. Have local cmpxchg 구현은 retry, 다른 구현은 local IRQ disable로 조건을 맞춥니다.'),detail('한도 비교','근사 오차가 한도 근처에서 중요합니다. Limited_add 같은 결합된 계약과 정확한 합 경로를 확인하고 별도 read 뒤 add를 원자 정책처럼 쓰지 않습니다.')])
    topic('Flex Proportions·기간별 비율','라이브러리·알고리즘','lib/flex_proportions.c','fprop_new_period',
      '최근 event 비율을 오래된 이력보다 더 반영하려면 전체·local count를 기간에 따라 감쇠시킬 수 있습니다.',
      'Flex proportions는 global/local event와 period를 관리하고 기간이 바뀌면 오래된 기여를 shift 기반으로 줄입니다. Local 상태는 global period와 차이를 맞추며 seqcount·percpu counter로 관찰과 업데이트를 연결합니다. 영구 누적 총합과 시간 감쇠된 비율은 다른 통계입니다.',
      'Global/local 구조를 초기화하고 event 증가·new_period·fraction API의 locking·기간 조건을 따릅니다. 샘플 적음·분모·integer rounding과 동시 event를 고려하며 기간 갱신 주체를 직렬화합니다.',
      'fprop_new_period의 events sum·events>>periods·차이 add·sequence 갱신을 읽으세요.',
      q('동시 변화 없는 events=8에서 periods=1 갱신 뒤 남는 global 기여는?','4','7','events 변수는 8-(8>>1)=4로 감소분을 계산하고 global에 -4를 더합니다. 결과는 4입니다. Shift 감쇠와 단순 하나 감소를 구분합니다.'),
      q('원본이 sum 결과를 바로 set하지 않고 감소량 add를 사용하는 이유는?','sum과 갱신 사이 발생한 event를 잃지 않기 위해','add는 항상 더 느린 문자열 처리라서','파일 주석은 sum과 set 사이 event 유실을 피하기 위해 addition을 쓴다고 설명합니다. Snapshot 뒤 새 입력이 생기는 경쟁을 고려합니다.'),
      details=[detail('Period 차이','각 local count가 마지막으로 반영한 period와 global period를 비교해 오래된 값을 조정합니다. 모든 CPU를 매 period에 즉시 같은 시각으로 바꾸는 구조라고 가정하지 않습니다.'),detail('정수 감쇠','Shift는 integer rounding을 가집니다. 작은 count·빈 event 상태의 특별 처리가 통계의 안정성과 분모에 영향을 줍니다.')])
    topic('DQL·완료율과 Queue Limit','라이브러리·알고리즘','lib/dynamic_queue_limits.c','dql_completed',
      '장치 queue를 너무 깊게 유지하면 latency가 늘고 너무 작게 유지하면 장치가 굶을 수 있습니다.',
      'Dynamic queue limits는 제출량·완료량·이전 interval과 slack을 비교해 필요한 queue limit을 조절합니다. Starvation 징후에 limit을 늘리고 지속된 여유에 줄이는 feedback을 사용하며 driver의 BQL에 연결될 수 있습니다. Byte count와 packet count·queue 개수를 혼합하면 안 됩니다.',
      'DQL/BQL consumer의 queued·completed 단위를 맞추고 producer/completion context·memory ordering 규약을 따릅니다. Min/max·hold time·reset과 완료된 양을 정확히 보고하며 scheduling qdisc와 hardware queue limit을 구분합니다.',
      'dql_completed의 num_queued·num_completed·inprogress·ovlimit·starved 판단을 읽으세요.',
      q('총 queued=1000, 이전 completed=700인데 이번 완료를 400으로 보고하면?','미완료 300보다 많아 계약 위반이다','항상 completed=1100이 유효하다','원본 BUG_ON은 count>queued-completed를 검사합니다. 한번 제출한 byte를 두 번 완료로 세거나 단위를 섞으면 안 됩니다.'),
      q('DQL limit을 크게 하면 모든 network latency가 반드시 줄어드는가?','장치 유휴와 queue 지연의 tradeoff를 측정한다','limit는 무조건 클수록 빠르다','깊은 queue는 data를 오래 대기시킬 수 있습니다. Feedback은 장치에 필요한 양과 불필요한 backlog를 조절하려는 목적입니다.'),
      details=[detail('관찰량','Num_queued-num_completed가 현재 진행 중인 양입니다. 새 완료 이후와 이전 interval 양을 비교해 starvation·slack을 추정합니다.'),detail('Cache Line','v6.12 주석은 stall_thrs를 num_queued와 같은 cache line에서 미리 읽어 false sharing 관찰 창을 줄이는 이유를 설명합니다. 알고리즘과 CPU cache 비용이 함께 고려됩니다.')])
    topic('DIM·샘플 기반 Interrupt 조절','라이브러리·알고리즘','lib/dim/net_dim.c','net_dim',
      'Interrupt를 너무 자주 처리하거나 너무 오래 묶는 비용을 현재 traffic 샘플로 조절할 수 있습니다.',
      'Dynamic interrupt moderation은 event·packet·byte·시간 차이로 통계를 만들고 profile의 효과를 비교하며 다음 moderation 값을 선택합니다. 측정·새 profile 적용·다시 측정 상태 기계로 동작합니다. 지원 driver가 worker에서 실제 hardware 설정을 적용하며 모든 latency 목표를 자동 최적화하는 것은 아닙니다.',
      '지원 driver의 DIM enable·sample update·profile callback을 관찰합니다. Counter 폭과 wrap·최소 event 수·measurement interval·work 수명을 맞추고 interrupt 횟수 감소와 end-to-end latency를 따로 측정합니다.',
      'net_dim의 DIM_MEASURE_IN_PROGRESS·BIT_GAP·DIM_NEVENTS·schedule_work·APPLY 상태를 읽으세요.',
      q('측정 event 차이가 DIM_NEVENTS보다 작으면 이 함수가 즉시 새 profile을 결정하는가?','측정을 더 모을 수 있도록 break한다','매 sample마다 hardware를 무조건 바꾼다','원본은 nevents가 기준보다 작으면 branch에서 나갑니다. 충분한 통계와 설정 적용 시점을 구분합니다.'),
      q('Profile 변경 결정이 나면 caller context에서 모든 hardware 변경을 직접 끝내는가?','APPLY 상태로 바꾸고 work를 예약한다','모든 callback은 interrupt 안에서 즉시 실행된다','원본은 DIM_APPLY_NEW_PROFILE로 상태를 바꾸고 schedule_work합니다. Generic 결정과 driver 적용 작업이 분리됩니다.'),
      details=[detail('Counter Wrap','Event counter 차이는 지정 u16 폭의 BIT_GAP으로 구합니다. 단순 signed subtraction으로 wrap 때 음수가 되는 계산과 다릅니다.'),detail('목표와 조건','Packets·bytes·event 비율과 profile 이동을 비교하는 정책입니다. 작은 packet·대량 traffic·latency sensitive 흐름은 같은 설정에서 다른 결과를 보일 수 있습니다.')])
